sys_ux_client_script.script:
function transform(input) {
    var output = [];
    var gr = new GlideRecord('sn_csm_business_location_internal');

    // Only fetch locations that have map coordinates
    gr.addNotNullQuery('latitude');
    gr.addNotNullQuery('longitude');
    gr.setLimit(500); 
    gr.query();

    while(gr.next()) {
        var obj = {
            // content formats the pop-over card when a pin is clicked
            content: '<h3>' + gr.getValue('name') + '</h3>' +
                     '<p>Status: ' + gr.getValue('status') + '</p>' +
                     '<p>Manager: ' + gr.getDisplayValue('manager') + '</p>',
            displayValue: '<h3>' + gr.getValue('name') + '</h3>',
            latitude: parseFloat(gr.getValue('latitude')),
            longitude: parseFloat(gr.getValue('longitude')),
            type: 'building' // Uses the standard map pin icon
        };
        output.push(obj);
    }
    return output;
}
